ALTER TABLE "TrainingEvent" ADD COLUMN "meetingUrl" TEXT, ADD COLUMN "timeZone" TEXT NOT NULL DEFAULT 'UTC', ADD COLUMN "provider" TEXT;
CREATE TABLE "TrainingScormPackage" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "courseId" TEXT NOT NULL, "title" TEXT NOT NULL, "version" TEXT NOT NULL, "launchUrl" TEXT NOT NULL, "manifest" JSONB NOT NULL, "checksum" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'READY', "createdById" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE, FOREIGN KEY ("courseId") REFERENCES "TrainingCourse"("id") ON DELETE CASCADE);
CREATE INDEX "TrainingScormPackage_tenantId_courseId_idx" ON "TrainingScormPackage"("tenantId","courseId");
CREATE TABLE "TrainingScormSession" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "packageId" TEXT NOT NULL, "userId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'IN_PROGRESS', "score" INTEGER, "progressPercent" INTEGER NOT NULL DEFAULT 0, "suspendData" JSONB, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastActivityAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), FOREIGN KEY ("packageId") REFERENCES "TrainingScormPackage"("id") ON DELETE CASCADE);
CREATE INDEX "TrainingScormSession_tenantId_userId_status_idx" ON "TrainingScormSession"("tenantId","userId","status");
CREATE TABLE "TrainingXapiStatement" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "userId" TEXT NOT NULL, "statementId" TEXT NOT NULL UNIQUE, "verb" TEXT NOT NULL, "objectId" TEXT NOT NULL, "result" JSONB, "context" JSONB, "occurredAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "TrainingXapiStatement_tenantId_userId_occurredAt_idx" ON "TrainingXapiStatement"("tenantId","userId","occurredAt");
CREATE TABLE "TrainingWebhook" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "endpointUrl" TEXT NOT NULL, "eventTypes" TEXT[] NOT NULL, "secretHash" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "lastStatus" TEXT, "lastError" TEXT, "lastDeliveryAt" TIMESTAMP(3), "createdById" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "TrainingWebhook_tenantId_isActive_idx" ON "TrainingWebhook"("tenantId","isActive");
CREATE TABLE "TrainingRecommendation" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "userId" TEXT NOT NULL, "courseId" TEXT NOT NULL, "reason" TEXT NOT NULL, "evidence" JSONB NOT NULL, "status" TEXT NOT NULL DEFAULT 'SUGGESTED', "decidedById" TEXT, "decidedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "TrainingRecommendation_tenantId_userId_status_idx" ON "TrainingRecommendation"("tenantId","userId","status");
INSERT INTO "Permission" ("id","code","name","description","createdAt","updatedAt") VALUES (gen_random_uuid()::text,'training.integrations.manage','Administrar integraciones formativas','Gestionar SCORM, xAPI y webhooks',NOW(),NOW()) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "RolePermission" ("roleId","permissionId") SELECT r."id",p."id" FROM "Role" r JOIN "Permission" p ON p."code"='training.integrations.manage' WHERE r."code" IN ('SUPERADMIN','PLATFORM_ADMIN','TENANT_ADMIN','HR_MANAGER','INSTRUCTOR') ON CONFLICT DO NOTHING;
